   123	/**
   124	 * Proxy Ticketmaster API requests
   125	 */
   126	async function fetchTicketmasterEvents(city = 'Stockholm', countryCode = 'SE', size = 50) {
   127	  const url = `https://app.ticketmaster.com/discovery/v2/events.json?apikey=${TICKETMASTER_API_KEY}&city=${city}&countryCode=${countryCode}&size=${size}&sort=date,asc`;
   128	  
   129	  console.log(`[api] Fetching Ticketmaster events for ${city}...`);
   130	  
   131	  try {
   132	    const response = await axios.get(url, { timeout: 15000 });
   133	    
   134	    if (response.status !== 200) {
   135	      console.log(`[api] Ticketmaster returned ${response.status}`);
   136	      return { error: `HTTP ${response.status}`, events: [] };
   137	    }
   138	    
   139	    const data = response.data;
   140	    
   141	    if (!data._embedded || !data._embedded.events) {
   142	      console.log(`[api] No events found`);
   143	      return { events: [], count: 0 };
   144	    }
   145	    
   146	    const events = data._embedded.events.map(ev => ({
   147	      id: ev.id,
   148	      title: ev.name,
   149	      date: ev.dates?.start?.localDate || '',
   150	      time: ev.dates?.start?.localTime ? ev.dates.start.localTime.substring(0, 5) : '',
   151	      venue: ev._embedded?.venues?.[0]?.name || 'Unknown',
   152	      area: ev._embedded?.venues?.[0]?.city?.name || city,
   153	      description: ev.info || ev.pleaseNote || '',
   154	      url: ev.url || '',
   155	      source: 'ticketmaster',
   156	      imageUrl: ev.images?.[0]?.url || null,
   157	      priceRanges: ev.priceRanges || [],
   158	    }));
   159	    
   160	    console.log(`[api] Ticketmaster: ${events.length} events`);
   161	    return { events, count: events.length };
   162	  } catch (error) {
   163	    console.error(`[api] Ticketmaster error: ${error.message}`);
   164	    return { error: error.message, events: [] };
   165	  }
   166	}
